import { invoiceTotals, lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';

export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => ['issued', 'partially_paid'].includes(inv.status))
    .filter(inv => inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: Math.floor((new Date(asOf) - new Date(inv.dueDate)) / (1000 * 60 * 60 * 24)),
      due: invoiceTotals(inv).total,
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const inv of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(inv.status)) continue;

    for (const line of inv.lines) {
      const rate = line.vatRate;
      const base = lineTotal(line) - lineDiscount(line);
      const vat = lineVAT(line);

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { base: 0, vat: 0 });
      }
      const current = vatMap.get(rate);
      current.base += base;
      current.vat += vat;
    }
  }

  return Array.from(vatMap)
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);
}

export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) return 0;

  const daysOverdue = Math.floor((new Date(asOf) - new Date(invoice.dueDate)) / (1000 * 60 * 60 * 24));
  const amountDue = invoiceTotals(invoice).total;
  const fee = roundCents(amountDue * 0.0004 * daysOverdue);
  return Math.max(0, fee);
}
